import java.util.*;
public class ChineseRemainderTheorem {public static void main(String[] args){Scanner sc=new Scanner(System.in);System.out.print("Enter number of equations: ");int n=sc.nextInt();long[] rem=new long[n],mod=new long[n];for(int i=0;i<n;i++){System.out.print("Enter remainder: ");rem[i]=sc.nextLong();System.out.print("Enter modulus: ");mod[i]=sc.nextLong();if(mod[i]<=0){System.out.println("Moduli must be positive.");return;}}long x=0,step=1;for(int i=0;i<n;i++){long r=Math.floorMod(rem[i],mod[i]),count=0;while(Math.floorMod(x,mod[i])!=r){x+=step;if(++count>10_000_000){System.out.println("Could not find a solution (possibly incompatible congruences).");return;}}long g=gcd(step,mod[i]);if((x-r)%g!=0){System.out.println("No solution for these congruences.");return;}step=lcm(step,mod[i]);}System.out.println("Solution: "+x);System.out.println("Combined modulus: "+step);}static long gcd(long a,long b){while(b!=0){long r=a%b;a=b;b=r;}return Math.abs(a);}static long lcm(long a,long b){return a/gcd(a,b)*b;}}
